def transform(grid):
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and c > 0 and w-c-1 == c:
            a = [row[:c] for row in grid]
            b = [row[c+1:] for row in grid]
            common = set(v for row in a for v in row) & set(v for row in b for v in row)
            base = next(iter(common))
            return [[3 if a[r][j] == b[r][j] else base for j in range(c)] for r in range(h)]
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]) and r > 0 and h-r-1 == r:
            a, b = grid[:r], grid[r+1:]
            common = set(v for row in a for v in row) & set(v for row in b for v in row)
            base = next(iter(common))
            return [[3 if a[i][c] == b[i][c] else base for c in range(w)] for i in range(r)]
    raise ValueError('No centered full separator')

